62	function formatLabel(value: number, labelFormatter: string | ((value: number) => string)): string {
63	    let label = value == null ? '' : (value + '');
64	    if (labelFormatter) {
65	        if (isString(labelFormatter)) {
66	            label = labelFormatter.replace('{value}', label);
67	        }
68	        else if (isFunction(labelFormatter)) {
69	            label = labelFormatter(value);
70	        }
71	    }
72	
73	    return label;
74	}
